declare namespace custom = "http://www.example.org/custom";
declare function custom:is-valid-id-format($id as xs:string?) as xs:boolean { (       matches(normalize-space($id), '^[A-Za-z0-9+\-_/]+$') and       not(matches($id, ' ')) and       not(starts-with($id, ' ')) and       not(ends-with($id, ' '))       ) };
declare function custom:is-valid-date-format($date as xs:string?) as xs:boolean { let $isFormatValid := (matches($date, '^20\d{2}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$')) return let $year := (xs:decimal(substring($date, 1, 4))) return let $month := (xs:decimal(substring($date, 6, 2))) return let $day := (xs:decimal(substring($date, 9, 2))) return let $isLeapYear := (($year mod 4 = 0 and $year mod 100 != 0) or ($year mod 400 = 0)) return let $maxDay := (       if ($month = (1, 3, 5, 7, 8, 10, 12)) then 31       else if ($month = (4, 6, 9, 11)) then 30       else if ($month = 2 and $isLeapYear) then 29       else if ($month = 2) then 28       else 0) return ($isFormatValid and $day le $maxDay) };
declare function custom:is-valid-document-type-code($code as xs:string?) as xs:boolean { let $custom_document-type-codes := ('380 389 393 501 386 500 384 471 472 473 261 262 381 396 502 503') return ($code = tokenize($custom_document-type-codes, '\s+')) };
declare function custom:is-valid-billing-mode($code as xs:string?) as xs:boolean { let $custom_billing-modes := ('B1 S1 M1 B2 S2 M2 S3 B4 S4 M4 S5 S6 B7 S7 B8 S8 M8 B9 S9 M9') return ($code = tokenize($custom_billing-modes, '\s+')) };
declare function custom:check-siret-siren-coherence($siret as xs:string?, $siren as xs:string?) as xs:boolean { (matches($siret, '^\d{14}$') and substring($siret, 1, 9) = $siren) };
declare function custom:is-valid-bar-treatment($value as xs:string?) as xs:boolean { ($value = ('B2B', 'B2BINT', 'B2C', 'B2CINT', 'OUTOFSCOPE', 'ARCHIVEONLY')) };
declare function custom:is-valid-eas-code($code as xs:string?) as xs:boolean { let $custom_eas-codes := ('AN AQ AS AU EM 0002 0007 0009 0037 0060 0088 0096 0097 0106        0130 0135 0142 0147 0151 0154 0158 0170 0177 0183 0184 0188 0190        0191 0192 0193 0194 0195 0196 0198 0199 0200 0201 0202 0203 0204        0205 0208 0209 0210 0211 0212 0213 0215 0216 0217 0218 0221 0225        0230 0235 0240 9910 9913 9914 9915 9918 9919 9920 9922 9923 9924        9925 9926 9927 9928 9929 9930 9931 9932 9933 9934 9935 9936 9937        9938 9939 9940 9941 9942 9943 9944 9945 9946 9947 9948 9949 9950        9951 9952 9953 9957 9959') return ($code = tokenize($custom_eas-codes, '\s+')) };
declare function custom:is-valid-vat-category-code($code as xs:string?) as xs:boolean { let $validCodes := (('S', 'E', 'AE', 'K', 'G', 'O', 'Z')) return ($code = $validCodes) };
declare function custom:is-valid-vat-rate($rate as xs:string?) as xs:boolean { let $validRates := ((       '0', '0.0', '0.00', '10', '10.0', '10.00', '13', '13.0', '13.00', '20', '20.0', '20.00',       '8.5', '8.50', '19.6', '19.60', '2.1', '2.10', '5.5', '5.50', '7', '7.0', '7.00',       '20.6', '20.60', '1.05', '0.9', '0.90', '1.75', '9.2', '9.20', '9.6', '9.60'       )) return ($rate = $validRates) };
declare function custom:is-valid-attachment-code($code as xs:string?) as xs:boolean { let $validCodes := ((       'RIB', 'LISIBLE', 'FEUILLE_DE_STYLE', 'PJA', 'BORDEREAU_SUIVI',       'DOCUMENT_ANNEXE', 'BON_LIVRAISON', 'BON_COMMANDE',       'BORDEREAU_SUIVI_VALIDATION', 'ETAT_ACOMPTE', 'FACTURE_PAIEMENT_DIRECT', 'RECAPITULATIF_COTRAITANCE'       )) return ($code = $validCodes) };
declare function custom:is-valid-schemeid-format($value as xs:string?) as xs:boolean { (matches($value, '^[A-Za-z0-9+\-_.]+$')) };
declare function custom:is-valid-decimal-19-2($amount as xs:string?) as xs:boolean { (matches($amount, '^[-]?\d{1,19}(\.\d{1,2})?$') and string-length(replace($amount, '\.', '')) le 19) };
declare function custom:is-valid-decimal-19-4($quantity as xs:string?) as xs:boolean { (matches($quantity, '^[-]?\d{1,19}(\.\d{1,4})?$') and string-length(replace($quantity, '\.', '')) le 19) };
declare function custom:is-valid-decimal-19-6-positive($amount as xs:string?) as xs:boolean { (matches($amount, '^\d{1,19}(\.\d{1,6})?$') and string-length(replace($amount, '\.', '')) le 19) };
declare function custom:is-valid-decimal-19-6($amount as xs:string?) as xs:boolean { (matches($amount, '^[-]?\d{1,19}(\.\d{1,6})?$') and string-length(replace($amount, '\.', '')) le 19) };
declare function custom:is-valid-percent-4-2-positive($percent as xs:string?) as xs:boolean { (matches($percent, '^\d{1,4}(\.\d{1,2})?$') and string-length(replace($percent, '\.', '')) le 4) };
declare function custom:isSpecialContract($context as element()?) as xs:boolean { (       exists($context/cbc:ProfileID)       and normalize-space($context/cbc:ProfileID) = ('S8', 'B8', 'M8', 'S9', 'B9', 'M9')) };
declare function custom:isSpecialContractMV($context as element()?) as xs:boolean { (       exists($context/cbc:ProfileID)       and normalize-space($context/cbc:ProfileID) = ('S8', 'B8', 'M8')) };
declare function custom:isSpecialContractBD($context as element()?) as xs:boolean { (       exists($context/cbc:ProfileID)       and normalize-space($context/cbc:ProfileID) = ('S9', 'B9', 'M9')) };
